<script setup>
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue'
import '../styles/task-map.css'
const props=defineProps({map:Object,initialTask:String,standalone:Boolean})
const emit=defineEmits(['navigate'])
const mode=ref('stories'),role=ref('all'),stage=ref('all'),status=ref('all'),query=ref(''),selectedId=ref('T01'),scenarioId=ref('S01'),priority=ref('all')
const lens=ref('target'),storyId=ref('N01'),coverage=ref('all'),flowId=ref('C01')
const modes=[{id:'stories',name:'故事地图与版本'},{id:'coverage',name:'流程覆盖检查'},{id:'overview',name:'全貌与角色'},{id:'scenarios',name:'场景与分支'},{id:'tasks',name:'任务详情'},{id:'gaps',name:'缺口与优先级'}]
const plan=computed(()=>props.map.planning)
const storyLookup=computed(()=>Object.fromEntries(plan.value.stories.map(s=>[s.id,s])))
const activeStory=computed(()=>storyLookup.value[storyId.value]||plan.value.stories[0])
const releases=computed(()=>plan.value.releases.filter(r=>lens.value==='target'||['本地已有','本地已实现'].includes(r.state)))
const flows=computed(()=>plan.value.flows.filter(f=>coverage.value==='all'||f.status===coverage.value))
const activeFlow=computed(()=>flows.value.find(f=>f.id===flowId.value)||flows.value[0])
const flowCounts=computed(()=>Object.fromEntries(Object.keys(plan.value.legend).map(k=>[k,plan.value.flows.filter(f=>f.status===k).length])))
const evidenceFor=ids=>plan.value.evidence.filter(e=>ids.includes(e.id))
const storiesIn=(release,activity)=>plan.value.stories.filter(s=>s.release_id===release&&s.activity_id===activity)
const activityGroups=id=>plan.value.task_groups.filter(g=>g.activity_id===id)
watch(lens,value=>{if(value==='current'&&activeStory.value.implementation!=='local')storyId.value='B01'})
async function openStory(id){storyId.value=id;mode.value='stories';if(storyLookup.value[id].implementation!=='local')lens.value='target';await nextTick();document.getElementById('map-story-heading')?.focus({preventScroll:true});document.getElementById('map-story-detail')?.scrollIntoView({block:'start',behavior:'auto'})}
const statusNames={local:'本地可用',partial:'部分支持',planned:'待实现',external:'待业务接入'}
const roleNames=computed(()=>Object.fromEntries(props.map.roles.map(r=>[r.id,r.name])))
const lookup=computed(()=>Object.fromEntries(props.map.tasks.map(t=>[t.id,t])))
const counts=computed(()=>Object.fromEntries(Object.keys(statusNames).map(k=>[k,props.map.tasks.filter(t=>t.availability===k).length])))
const filtered=computed(()=>props.map.tasks.filter(t=>(role.value==='all'||t.role===role.value)&&(stage.value==='all'||String(t.stage)===stage.value)&&(status.value==='all'||t.availability===status.value)&&[t.id,t.title,t.trigger,t.done,t.gap].join(' ').toLowerCase().includes(query.value.trim().toLowerCase())))
const activeTask=computed(()=>filtered.value.find(t=>t.id===selectedId.value)||filtered.value[0])
const scenario=computed(()=>props.map.scenarios.find(s=>s.id===scenarioId.value)||props.map.scenarios[0])
const gaps=computed(()=>props.map.tasks.filter(t=>t.availability!=='local'&&(priority.value==='all'||t.priority===priority.value)).sort((a,b)=>a.priority.localeCompare(b.priority)||a.id.localeCompare(b.id,undefined,{numeric:true})))
const stageTasks=(index,actor)=>props.map.tasks.filter(t=>t.stage===index&&(!actor||t.role===actor))
watch(mode,value=>{if(props.standalone&&value!=='tasks')window.history.replaceState(null,'',window.location.pathname+window.location.search)})
function syncTaskHash(){const id=window.location.hash.slice(1);if(props.standalone&&lookup.value[id])openTask(id)}
onMounted(()=>{if(props.standalone)window.addEventListener('hashchange',syncTaskHash);if(props.initialTask&&lookup.value[props.initialTask])openTask(props.initialTask)})
onUnmounted(()=>window.removeEventListener('hashchange',syncTaskHash))
function reset(){role.value='all';stage.value='all';status.value='all';query.value=''}
async function openTask(id){reset();selectedId.value=id;mode.value='tasks';if(props.standalone)window.history.replaceState(null,'','#'+id);await nextTick();document.getElementById('map-task-heading')?.focus({preventScroll:true});document.getElementById('map-task-detail')?.scrollIntoView({block:'start',behavior:'auto'})}
async function openStage(index){reset();stage.value=String(index);mode.value='tasks';await nextTick();document.getElementById('map-task-filters')?.scrollIntoView({block:'start',behavior:'auto'})}
function download(){const url=URL.createObjectURL(new Blob([JSON.stringify({...props.map,title:'知应 用户任务地图'},null,2)],{type:'application/json;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='知应-用户任务地图-v5.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
</script>
<template>
<div class="task-map-v2">
  <section class="map-goal"><div><span class="map-eyebrow">售后服务 · 用户故事与任务地图 V5 · {{plan.updated_at}}</span><h2>{{map.goal}}</h2><p>{{map.audience}}</p></div><button class="secondary" @click="download">导出完整地图</button></section>
  <p class="map-plan-decision">{{plan.purpose}} {{plan.decision}}</p>
  <p class="map-evidence-note">设计依据：{{map.research.basis}}。{{map.research.limits}}</p>
  <div class="map-coverage" role="group" aria-label="支持情况概览"><span v-for="(name,key) in statusNames" :key="key"><b>{{counts[key]}}</b>{{name}}</span><span><b>{{map.scenarios.length}}</b>典型场景</span></div>
  <div class="map-mode-switch" role="group" aria-label="地图视图"><button v-for="item in modes" :key="item.id" :aria-pressed="mode===item.id" :class="{selected:mode===item.id}" @click="mode=item.id">{{item.name}}</button></div>

  <section v-if="mode==='stories'" class="map-stories">
    <div class="map-section-title"><h2>沿业务顺序展开，再按完整流程安排版本</h2><p>角色与目标 → 活动 → 用户任务 → 具体需求。点击需求卡查看受益目标、前置条件、验收标准与依据。各建议版本继承已有能力。</p></div>
    <div class="map-detail-filters"><div class="map-lens" role="group" aria-label="现状与目标"><button class="secondary" :class="{chosen:lens==='current'}" :aria-pressed="lens==='current'" @click="lens='current'">现状 · 本地已有</button><button class="secondary" :class="{chosen:lens==='target'}" :aria-pressed="lens==='target'" @click="lens='target'">目标 · 含建议版本</button></div><span>{{plan.task_groups.length}} 组用户任务 · {{plan.stories.length}} 条需求故事</span></div>
    <div class="map-story-scroll" tabindex="0" role="region" aria-label="用户故事地图，窄屏可在表内横向滚动"><table class="map-story-table"><caption>横向为业务活动；纵向为继承基线的版本范围。支撑能力放在具体需求层。空格表示沿用已有流程。</caption><thead><tr><th scope="col">版本 / 业务活动</th><th v-for="a in plan.activities" :key="a.id" scope="col"><small>{{a.id}}</small>{{a.title}}<p>{{a.outcome}}</p></th></tr></thead><tbody><tr class="map-story-tasks"><th scope="row">用户任务</th><td v-for="a in plan.activities" :key="a.id"><details v-for="g in activityGroups(a.id)" :key="g.id" class="map-task-group"><summary>{{g.title}}<small>{{g.task_ids.length}} 项原任务 · 展开核对</small></summary><button v-for="id in g.task_ids" :key="id" class="text-button" @click="openTask(id)">{{id}} {{lookup[id].title}}<br/>{{statusNames[lookup[id].availability]}}</button></details></td></tr><tr v-for="r in releases" :key="r.id" :class="['map-release-row',r.id]"><th scope="row"><small>{{r.state}}</small>{{r.name}}<p>{{r.goal}}</p><small v-if="r.inherits.length">继承 {{r.inherits.join('、')}}</small></th><td v-for="a in plan.activities" :key="a.id"><button v-for="s in storiesIn(r.id,a.id)" :key="s.id" :class="['map-story-card',{selected:activeStory.id===s.id}]" :aria-pressed="activeStory.id===s.id" @click="openStory(s.id)"><small>{{s.id}} · {{s.implementation==='local'?'本地已有':'目标需求'}}</small><strong>{{s.title}}</strong></button><span v-if="!storiesIn(r.id,a.id).length" class="map-no-task">沿用基线 / 无新增</span></td></tr></tbody></table></div>
    <article id="map-story-detail" class="map-story-detail"><span class="map-eyebrow">{{activeStory.id}} · {{activeStory.release_id}} · {{activeStory.acceptance_state}}</span><h3 id="map-story-heading" tabindex="-1">{{activeStory.title}}</h3><p class="source-note">主要角色：{{activeStory.role_ids.map(id=>roleNames[id]).join('、')}} · 业务验证：待真实客服观察</p><p class="map-result"><strong>用户希望：</strong>{{activeStory.benefit}}</p><div class="map-inline-links"><button v-for="id in activeStory.task_ids" :key="id" class="text-button" @click="openTask(id)">{{id}} {{lookup[id].title}} · {{statusNames[lookup[id].availability]}}</button></div><h4>具体场景的验收条件</h4><ol class="map-acceptance"><li v-for="(c,index) in activeStory.acceptance" :key="index"><p><b>前提</b>{{c.given}}</p><p><b>操作</b>{{c.when}}</p><p><b>预期</b>{{c.then}}</p></li></ol><p v-if="activeStory.depends_on.length"><strong>相关前置：</strong><button v-for="id in activeStory.depends_on" :key="id" class="text-button" @click="openStory(id)">{{id}} {{storyLookup[id].title}}</button></p><h4>依据与验证边界</h4><div class="map-evidence-list"><article v-for="e in evidenceFor(activeStory.evidence_ids)" :key="e.id"><strong>{{e.id}} · {{e.kind}} · {{e.title}}</strong><p>{{e.detail}}</p><code v-if="e.path">{{e.path}}</code></article></div></article>
    <div class="map-section-title"><h2>每一轮需要验收到什么程度</h2><p>覆盖状态以当前产品为准；建议版本没有被标成已实现。</p></div><div class="map-release-notes"><article v-for="r in releases" :key="r.id"><span class="map-eyebrow">{{r.id}} · {{r.state}}</span><h3>{{r.name}}</h3><p>{{r.exit}}</p></article></div>
    <details class="map-methods"><summary>地图的用途、方法依据与维护信息</summary><p>{{plan.scope}}</p><p>维护责任：{{plan.owner}} · 更新：{{plan.updated_at}}</p><article v-for="m in plan.methods" :key="m.name"><h3><a :href="m.url" target="_blank" rel="noopener noreferrer">{{m.name}}</a></h3><p>{{m.use}}</p></article></details>
  </section>

  <section v-else-if="mode==='coverage'" class="map-audit">
    <div class="map-section-title"><h2>当前产品能否走通这些流程</h2><p>依据当前界面、请求模型及本地测试核对。覆盖状态描述产品能力；所有流程的业务价值与真实使用效果仍待实际客服验证。</p></div>
    <section v-if="plan.assistant_acceptance" class="map-assistant-acceptance"><h2>{{plan.assistant_acceptance.title}}</h2><p>隔离回归：修复前 {{plan.assistant_acceptance.baseline_passed}} / {{plan.assistant_acceptance.cases.length}} 组通过 → 修复后 {{plan.assistant_acceptance.after_passed}} / {{plan.assistant_acceptance.cases.length}} 组通过。</p><p class="source-note">{{plan.assistant_acceptance.scope}}</p><details v-for="c in plan.assistant_acceptance.cases" :key="c.id" class="map-methods"><summary>{{c.id}} · {{c.title}} · {{c.after==='passed'?'隔离回归通过':'仍待修复'}}</summary><p><strong>为什么测试：</strong>{{c.reason}}</p><p><strong>前提：</strong>{{c.given}}</p><p><strong>输入：</strong>{{c.input}}</p><p><strong>正确结果：</strong>{{c.expected}}</p><p><strong>不能出现：</strong>{{c.forbidden}}</p><p>修复前：{{c.baseline==='passed'?'通过':'未通过'}}；修复后：{{c.after==='passed'?'通过':'未通过'}}。</p><p class="source-note">{{c.method}}<br/>真实模型检查：{{c.live}}</p><div class="map-inline-links"><button v-for="id in c.task_ids" :key="id" class="text-button" @click="openTask(id)">{{id}} {{lookup[id].title}}</button></div></details></section>
    <details v-if="plan.latest_trial" class="map-methods" open><summary>此前业务试用 · {{plan.latest_trial.date}} · {{plan.latest_trial.issues.length}} 项待修复问题</summary><p>{{plan.latest_trial.method}}</p><p>已复现问题保留在覆盖结论中，以下不代表已经修复。</p><article v-for="issue in plan.latest_trial.issues" :key="issue.id"><h3>{{issue.priority}} · {{issue.title}}</h3><p>{{issue.expected}}</p><div class="map-inline-links"><button v-for="id in issue.tasks" :key="id" class="text-button" @click="openTask(id)">{{id}} {{lookup[id].title}}</button></div></article><p v-for="item in plan.latest_trial.limitations" :key="item" class="source-note">{{item}}</p></details><ol class="map-audit-process"><li v-for="step in plan.workflow" :key="step">{{step}}</li></ol>
    <div class="map-coverage"><span v-for="(name,key) in plan.legend" :key="key"><b>{{flowCounts[key]}}</b>{{name}}</span></div>
    <div class="map-detail-filters"><label>流程覆盖情况<select v-model="coverage" aria-label="流程覆盖情况"><option value="all">全部流程</option><option v-for="(name,key) in plan.legend" :key="key" :value="key">{{name}}</option></select></label><span role="status">{{flows.length}} 条流程 · 业务验证待完成</span></div>
    <div v-if="activeFlow" class="map-scenario-layout"><nav aria-label="覆盖检查流程"><button v-for="f in flows" :key="f.id" :class="{selected:activeFlow.id===f.id}" :aria-pressed="activeFlow.id===f.id" @click="flowId=f.id"><small>{{f.id}} · {{plan.legend[f.status]}}</small>{{f.title}}</button></nav><article class="map-flow-detail"><span :class="['map-status',activeFlow.status==='covered'?'local':activeFlow.status]">{{plan.legend[activeFlow.status]}}</span><h3>{{activeFlow.title}}</h3><p><strong>评估范围：</strong>{{activeFlow.scope}}</p><p class="map-result"><strong>当前结论：</strong>{{activeFlow.gap}}</p><h4>逐步核对</h4><ol class="map-flow-checks"><li v-for="c in activeFlow.checks" :key="c.id"><strong>{{c.text}}</strong><span :class="['map-status',c.result==='covered'?'local':c.result]">{{plan.legend[c.result]}}</span><small>依据：{{c.evidence_ids.join('、')}}</small></li></ol><h4>对应的修改需求</h4><div class="map-inline-links"><button v-for="id in activeFlow.next_story_ids" :key="id" class="text-button" @click="openStory(id)">{{id}} {{storyLookup[id].title}} →</button><span v-if="!activeFlow.next_story_ids.length">当前限定范围保留回归检查。</span></div><h4>回到原任务 / 场景</h4><div class="map-inline-links"><button v-for="id in activeFlow.task_ids" :key="id" class="text-button" @click="openTask(id)">{{id}} {{lookup[id].title}}</button><button v-for="id in activeFlow.scenario_ids" :key="id" class="text-button" @click="scenarioId=id;mode='scenarios'">{{id}} 场景与异常分支</button></div><h4>证据说明</h4><div class="map-evidence-list"><article v-for="e in evidenceFor([...new Set(activeFlow.checks.flatMap(c=>c.evidence_ids))])" :key="e.id"><strong>{{e.id}} · {{e.kind}}</strong><p>{{e.detail}}</p><code v-if="e.path">{{e.path}}</code></article></div></article></div><p v-else class="map-empty">当前分类没有流程。可选择全部流程。</p>
    <div class="map-section-title"><h2>统一修改前，需要明确的业务规则</h2><p>这些是待确认的研究问题；目前没有访谈结果或效果基线。</p></div><div class="map-release-notes"><article v-for="q in plan.research_queue" :key="q.question"><h3>{{q.question}}</h3><p>影响：{{q.decision}}</p><small>{{q.owner}}</small></article></div><div class="map-section-title"><h2>修改后怎样衡量效果</h2></div><div class="map-release-notes"><article v-for="m in plan.metrics" :key="m.name"><h3>{{m.name}}</h3><p>{{m.definition}}</p><small>当前基线：{{m.baseline}} · 目标：{{m.target}}</small></article></div>
  </section>

  <section v-else-if="mode==='overview'" class="map-overview">
    <div class="map-section-title"><h2>一件客户问题，怎样走到明确结果</h2><p>阶段中的任务可以反复进入；材料不全、交接失败或客户再次联系时，需要回到相应环节。</p></div>
    <div class="map-backbone"><article v-for="s in map.stage_details" :key="s.id"><header><span>{{String(s.id+1).padStart(2,'0')}}</span><h3>{{s.name}}</h3></header><p class="stage-goal">{{s.goal}}</p><dl><dt>输入</dt><dd>{{s.inputs.join('、')}}</dd><dt>产出</dt><dd>{{s.output}}</dd></dl><p class="map-branch-note">{{s.exception}}</p><button class="text-button" @click="openStage(s.id)">查看此阶段 {{s.task_ids.length}} 项任务 →</button></article></div>
    <div class="map-section-title"><h2>谁负责把哪部分工作办成</h2><p>按主要责任角色组织任务，跨角色协作在场景中展开。</p></div>
    <div class="map-role-cards"><article v-for="r in map.roles" :key="r.id"><h3>{{r.name}}</h3><p>{{r.goal}}</p><small>交付：{{r.deliverable}}</small></article></div>
    <div class="map-swimlane"><table><caption>角色 × 阶段 · 点击任务查看详情（窄屏可在表内横向查看）</caption><thead><tr><th scope="col">主要角色</th><th v-for="s in map.stages" :key="s" scope="col">{{s}}</th></tr></thead><tbody><tr v-for="r in map.roles" :key="r.id"><th scope="row">{{r.name}}</th><td v-for="(s,index) in map.stages" :key="s"><button v-for="t in stageTasks(index,r.id)" :key="t.id" :class="['map-task-link',t.availability]" @click="openTask(t.id)"><small>{{t.id}} · {{statusNames[t.availability]}}</small>{{t.title}}</button><span v-if="!stageTasks(index,r.id).length" class="map-no-task">—</span></td></tr></tbody></table></div>
    <section class="map-checkpoints"><h2>怎样判断业务结果</h2><div><article v-for="m in map.metrics" :key="m.name"><h3>{{m.name}}</h3><p>{{m.definition}}</p><small>{{m.status}}</small><div class="map-inline-links"><button v-for="id in m.tasks" :key="id" class="text-button" @click="openTask(id)">{{id}} {{lookup[id].title}}</button></div></article></div></section>
  </section>

  <section v-else-if="mode==='scenarios'" class="map-scenarios"><div class="map-section-title"><h2>用具体场景推演正常与异常路径</h2><p>这是设计推演；只有带“本地可用”的节点已经具备本地流程支持。</p></div><div class="map-scenario-layout"><nav aria-label="典型业务场景"><button v-for="s in map.scenarios" :key="s.id" :class="{selected:scenario.id===s.id}" :aria-pressed="scenario.id===s.id" @click="scenarioId=s.id"><small>{{s.id}} · {{roleNames[s.actor]}}</small>{{s.title}}</button></nav><div class="map-scenario-detail"><header><span class="map-eyebrow">{{scenario.id}} · {{roleNames[scenario.actor]}}</span><h3>{{scenario.title}}</h3><p><strong>触发：</strong>{{scenario.trigger}}</p><p><strong>输入：</strong>{{scenario.input}}</p><p class="map-result"><strong>期望结果：</strong>{{scenario.outcome}}</p></header><h4>主路径 · 点击节点查看任务</h4><ol class="map-path"><li v-for="id in scenario.task_ids" :key="id"><button @click="openTask(id)"><small>{{id}} · {{roleNames[lookup[id].role]}}</small><strong>{{lookup[id].title}}</strong><span :class="['map-status',lookup[id].availability]">{{statusNames[lookup[id].availability]}}</span></button></li></ol><h4>遇到这些情况，走哪条路</h4><article v-for="(d,index) in scenario.decisions" :key="d.at+index" class="map-decision"><h5>{{d.question}}</h5><div><p><b>条件满足</b>{{d.yes}}</p><p><b>条件不满足 / 需要分流</b>{{d.no}}</p></div><div class="map-inline-links"><button v-for="id in d.refs" :key="id" class="text-button" @click="openTask(id)">{{id}} {{lookup[id].title}}</button></div></article><template v-if="scenario.handoffs.length"><h4>跨角色交接要交付什么</h4><article v-for="h in scenario.handoffs" :key="h.task+h.to_role" class="map-handoff"><strong>{{roleNames[h.from_role]}} → {{roleNames[h.to_role]}}</strong><p>{{h.artifact}}</p><button class="text-button" @click="openTask(h.task)">检查交接任务 {{h.task}}</button></article></template></div></div></section>

  <section v-else-if="mode==='tasks'" class="map-task-directory"><div class="map-section-title"><h2>任务详情与验收条件</h2><p>从输入、依赖到产出，检查当前支持与剩余缺口。</p></div><div id="map-task-filters" class="map-detail-filters"><label>角色<select v-model="role" aria-label="任务角色"><option value="all">全部角色</option><option v-for="r in map.roles" :key="r.id" :value="r.id">{{r.name}}</option></select></label><label>阶段<select v-model="stage" aria-label="任务阶段"><option value="all">所有阶段</option><option v-for="(s,i) in map.stages" :key="s" :value="String(i)">{{s}}</option></select></label><label>支持情况<select v-model="status" aria-label="任务支持情况"><option value="all">全部支持情况</option><option v-for="(name,key) in statusNames" :key="key" :value="key">{{name}}</option></select></label><label class="map-search">查找任务<input v-model="query" type="search" aria-label="查找地图任务" placeholder="任务、卡点或编号…"/></label><button class="text-button" @click="reset">清除筛选</button><span role="status">{{filtered.length}} 项任务</span></div>
    <div v-if="filtered.length" class="map-detail-layout"><nav aria-label="地图任务列表"><button v-for="t in filtered" :key="t.id" :class="{selected:activeTask.id===t.id}" :aria-pressed="activeTask.id===t.id" @click="selectedId=t.id"><small>{{t.id}} · {{statusNames[t.availability]}}</small>{{t.title}}</button></nav><article id="map-task-detail" class="map-task-detail" v-if="activeTask"><header><span class="map-eyebrow">{{activeTask.id}} · {{roleNames[activeTask.role]}} · {{map.stages[activeTask.stage]}}</span><h3 id="map-task-heading" tabindex="-1">{{activeTask.title}}</h3><p v-if="activeTask.known_issue_ids?.length" class="map-evidence-note">另有待修复问题：{{activeTask.known_issue_ids.join('、')}}。请在流程覆盖检查中核对异常分支，不能把“本地可用”理解为全部异常通过。</p><span :class="['map-status',activeTask.availability]">{{statusNames[activeTask.availability]}}</span></header><p class="map-result"><strong>用户想办成：</strong>当{{activeTask.trigger}}，希望{{activeTask.title}}，使{{activeTask.done}}。</p><dl class="map-task-facts"><dt>需要的输入</dt><dd>{{activeTask.inputs.join('、')}}</dd><dt>完成后产出</dt><dd>{{activeTask.output}}</dd><dt>相关前置</dt><dd><button v-for="id in activeTask.depends_on" :key="id" class="text-button" @click="openTask(id)">{{id}} {{lookup[id].title}}</button><span v-if="!activeTask.depends_on.length">可从此任务开始；需核对输入是否齐全</span><small v-else class="map-dependency-note">按场景选用的前置检查，不要求每项工作全部执行。</small></dd></dl><h4>需求故事与验证状态</h4><p class="source-note">{{activeTask.level}} · {{activeTask.research_state}}</p><div class="map-inline-links"><button v-for="id in activeTask.story_ids" :key="id" class="text-button" @click="openStory(id)">{{id}} {{storyLookup[id].title}} →</button></div><h4>操作路径</h4><ol><li v-for="step in activeTask.steps" :key="step">{{step}}</li></ol><p v-if="activeTask.acceptance_case_ids?.length" class="source-note">已关联助手验收：{{activeTask.acceptance_case_ids.join("、")}}；在流程覆盖检查中核对标准和验证范围。</p><h4>完成与异常验收</h4><ul><li v-for="item in activeTask.acceptance" :key="item">{{item}}</li><li>{{activeTask.exception}}</li></ul><div class="map-support"><h4>当前产品支持</h4><p>{{activeTask.current_support}}</p><h4>剩余缺口 / 适用边界</h4><p>{{activeTask.gap}}</p></div><dl class="map-task-facts"><dt>信息依据</dt><dd>{{activeTask.source}}</dd><dt>频率证据</dt><dd>{{activeTask.frequency}}</dd><dt>如何验证</dt><dd>{{activeTask.verification}}</dd><dt>优先级判断</dt><dd>{{activeTask.priority==='baseline'?'当前本地基线':activeTask.priority+' · '+activeTask.priority_status}}<br/>{{activeTask.priority_reason}}<br/>待核实：{{activeTask.validation}}</dd></dl><div class="map-inline-links"><button v-for="id in activeTask.scenario_ids" :key="id" class="text-button" @click="scenarioId=id;mode='scenarios'">放回 {{id}} 场景查看</button></div><button v-if="['local','partial'].includes(activeTask.availability)" class="secondary" @click="emit('navigate',{view:activeTask.view})">进入当前支持的操作</button><p v-else class="source-note">此任务尚未实现完整操作；可在“缺口与优先级”中讨论下一步。</p></article></div><div v-else class="map-empty" role="status">没有符合筛选的任务。<button class="text-button" @click="reset">恢复全部任务</button></div>
  </section>

  <section v-else class="map-gaps"><div class="map-section-title"><h2>还缺什么，先验证什么</h2><p>优先级依据任务中断与结果闭环提出；没有真实业务频率、损失或成本样本，不生成虚假的评分与排期。</p></div><div class="map-roadmap"><article v-for="slice in map.roadmap" :key="slice.title"><h3>{{slice.title}}</h3><p>{{slice.description}}</p><button v-for="id in slice.task_ids" :key="id" class="text-button" @click="openTask(id)">{{id}} {{lookup[id].title}}</button></article></div><div class="map-detail-filters"><label>建议优先级<select v-model="priority" aria-label="缺口优先级"><option value="all">全部建议</option><option value="P1">P1 · 优先验证闭环与前置条件</option><option value="P2">P2 · 随后验证协作与一致性</option><option value="P3">P3 · 后续分析深化</option></select></label><span role="status">{{gaps.length}} 项待验证需求</span></div><article v-for="t in gaps" :key="t.id" class="map-gap-card"><header><div><span class="map-eyebrow">{{t.id}} · {{roleNames[t.role]}} · {{map.stages[t.stage]}}</span><h3>{{t.title}}</h3></div><span class="map-priority">{{t.priority}} · 建议</span></header><p><strong>当前卡点：</strong>{{t.gap}}</p><p><strong>为什么考虑优先做：</strong>{{t.priority_reason}}（影响：{{t.impact}}）</p><p><strong>先验证：</strong>{{t.validation}}</p><p class="source-note">{{statusNames[t.availability]}} · {{t.source}} · {{t.frequency}}</p><button class="text-button" @click="openTask(t.id)">核对完整任务与验收标准 →</button></article><section class="map-research"><h3>下一轮业务试用要问的六个问题</h3><ol><li v-for="q in map.research.questions" :key="q">{{q}}</li></ol><p>{{map.research.limits}}</p></section></section>
  <p class="map-scope">{{map.scope}}</p>
</div>
</template>
